(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pl"] = {"ui":{"skip":"Przejdź do treści","back":"← Wróć do AI-gile","lang.button":"Język: {name}","lang.dialog":"Wybierz język","lang.search":"Szukaj języków","lang.none":"Nie znaleziono języka","lang.notYet":"{name} nie jest jeszcze przetłumaczony","theme.aria":"Przełącz motyw: jasny, ciemny lub czarny","theme.toLight":"Przełącz na jasny motyw","theme.toDark":"Przełącz na ciemny motyw","theme.toBlack":"Przełącz na czarny motyw (prawdziwa czerń, przyjazna ekranom OLED)","words.underline":"Podkreśl te słowa na stronie","words.underlineHelp":"Najedź kursorem na słowo z kropkowanym podkreśleniem albo je dotknij, żeby zobaczyć, co znaczy.","words.col.todo":"Karty wybrane na teraz: zespół zabierze się za nie w następnej kolejności.","words.col.doing":"Jedna AI pracuje nad tą kartą właśnie teraz.","words.col.review":"Jedna AI skończyła pracę; zanim trafi do Ciebie, sprawdza ją druga.","words.col.verify":"Czeka na Ciebie: wypróbuj i daj znać, czy działa.","words.col.team":"Twoje notatki lub odpowiedzi, czekające, aż zespół je odbierze.","words.col.done":"Zakończone i zaakceptowane.","index.title":"AI-gile: Twój zespół AI do programowania, na jednej tablicy","index.description":"AI-gile to tablica kanban dla zespołów programistycznych AI. Pracują, gdy Ty śpisz; Ty dostajesz jeden krótki stos spraw do rozstrzygnięcia, przetestowania i zaakceptowania.","hero.logoAlt":"Ikona tablicy AI-gile","hero.h1.html":"Twój zespół AI do programowania, na jednej&nbsp;tablicy.","hero.alpha":"🐣 Zamknięta pre-alfa","hero.alphaTitle":"Wczesna i niedokończona: dzięki, że próbujesz!","hero.lede":"Budują, gdy śpisz. Budzisz się przy jednym krótkim stosie: kilka pytań, kilka rzeczy do przetestowania, fioletowy diament czy dwa. Klik, akceptacja i z powrotem do kawy.","dl.windows":"Aplikacja na Windows","dl.browser":"Uruchom w przeglądarce","dl.messenger":"📱 Messenger na telefon","dl.soon":"Wkrótce","dl.notify":"🔔 Powiadom mnie, gdy ruszy","dl.notifySmall":"Alfa lub beta","hero.secondary":"Agile, ale zespół nigdy nie potrzebuje kawy na stojąco. (I tak robią stand-upy.)","pitch.h2":"AI-gile w tylu słowach, ilu chcesz","pitch.lede":"Wybierz długość, od jednego słowa do 144. Każda długość to osobny opis, napisany właśnie na ten rozmiar. Przeciągnij suwak albo użyj strzałek.","pitch.rangeLabel":"Długość w słowach","pitch.dice":"🎲 inna wersja","pitch.words.one":"{n} słowo","pitch.words.other":"{n} słowa","pitch.letters.one":"{n} litera","pitch.letters.other":"{n} litery","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znaku","count.line.html.one":"{n} karta na tablicy w tej chwili","count.line.html.other":"{n} karty na tablicy w tej chwili","people.humans.html.one":"👥 {n} osoba","people.humans.html.other":"👥 {n} osób","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agentów","people.working.html.one":"⚡ {n} w pracy w tej chwili","people.working.html.other":"⚡ {n} w pracy w tej chwili","pre.title":"AI-gile: coś tu powstaje","pre.description":"Coś tu powstaje: tablica, na której zespoły AI budują to, o co prosisz, i przy okazji cię uczą. Na razie zamknięta pre-alfa z przyjaciółmi.","pre.h1":"Coś tu powstaje. 🤫","pre.line":"Tablica, na której zespoły AI budują to, o co prosisz, i przy okazji cię uczą. Na razie zamknięta pre-alfa z przyjaciółmi.","pre.btn":"🔔 Powiadom mnie, gdy ruszy","pre.peek":"Za szybą: prawdziwa tablica, na żywo. Każda karta to kolorowy pasek.","pre.peekFake":"Za szybą: tak wygląda tablica w akcji.","pre.night":"🌙 Nocny stróż trzyma pieczę nad wszystkim · 😴 człowiek odpoczywa","features.aria":"Co robi","f.pile.h":"Jeden stos dla Ciebie","f.pile.html":"<b>Dla Ciebie</b> zbiera wszystko, co czeka na Ciebie, we wszystkich projektach: pytania, rzeczy do przetestowania, zadania tylko dla człowieka. Twoja kolejka mówi, co dalej i ile to zajmie.","f.sleep.h":"Zespoły, które pracują, gdy śpisz","f.sleep.p":"Każdy projekt ma lidera i zespół agentów AI. Skomentuj kartę, a zespół się budzi, robi swoje i oddaje ją z krokami, które zrozumie zmęczony człowiek.","f.tester.h":"Najpierw sprawdza tester AI","f.tester.p":"Zanim cokolwiek do Ciebie trafi, tester wykonuje kroki w kopii aplikacji i pokazuje, co zobaczył, ze zrzutem ekranu. Przejrzyj te, które przeszły, i zaakceptuj jednym kliknięciem.","f.proof.h":"Dowody, nie obietnice","f.proof.p":"Każde przekazanie pokazuje, co się zmieniło: pliki, diff, zrzuty ekranu. Bez otwierania każdej aplikacji, żeby sprawdzić, czy już gotowe.","f.chat.h":"Rozmawiaj ze swoimi liderami","f.chat.p":"Pasek w stylu Discorda: jedna ikona na projekt, fioletowe diamenty przy tym, co czeka na Ciebie. Napisz do lidera pomysł; zamieni go w karty i plan, z przyciskiem ✅ Go.","f.tidy.h":"Sam dba o porządek","f.tidy.p":"Powiązane karty zlewają się w jedną, zagmatwane tytuły są poprawiane, a kontrola tokenów utrzymuje kod szczupłym. Mniej rzeczy do przełączania, mniej do myślenia.","f.private.h":"Twoje, na Twoim komputerze","f.private.li1":"Tablica działa na Twojej własnej maszynie i odpowiada tylko Tobie.","f.private.li2":"Prywatne wiadomości między ludźmi są szyfrowane od końca do końca.","f.private.li3":"Bez kont, bez trackerów, bez ciasteczek.","f.lang.h":"W Twoim języku","f.lang.p":"Ponad 120 języków, od niderlandzkiego, walijskiego i japońskiego po piracki, Yodę i klingoński, z szybkim przełącznikiem na angielski dla żargonu branżowego.","f.service.h":"Od pomysłu do prawdziwej usługi","f.service.p":"Udało Ci się zbudować z AI coś, z czego ludzie już korzystają? Oznacz to jako usługę, a tablica pomoże Ci dobrze ją prowadzić: sprawdzanie dostępności, publiczna strona statusu, incydenty z opisem, zmiany, które wymagają Go, kopie zapasowe sprawdzane codziennie. Pomoc uczy każdego kroku po drodze.","msgr.h2":"AI-gile Messenger: Twój zespół w kieszeni","msgr.p1":"Rozmawiaj ze swoim zespołem AI bez otwierania tablicy. Czatuj z liderami projektów i znajomymi, przeglądaj kroki testowe kart i odpowiadaj na nie, wszystko z telefonu.","msgr.p2":"Aby go sparować, zeskanuj kod QR na swojej tablicy. Pierwszy raz? Przyjazny czat demo wszystko Ci pokaże.","msgr.when":"Najpierw Android, potem wersja przeglądarkowa na telefony i iPhone.","msgr.who":"Twój lider projektu","msgr.b1":"Poprawka trybu ciemnego jest gotowa. Podesłać kroki testowe?","msgr.b2":"Tak, poproszę!","msgr.b3":"1. Otwórz Ustawienia. 2. Wybierz Ciemny. Wygląda dobrze?","tl.aria":"Oś czasu od pierwszej rozmowy do planów","tl.h2":"Od pierwszej rozmowy do tego, co dalej","tl.lede":"Prawdziwe daty i godziny, w Twojej strefie czasowej. Po dzisiejszym dniu to plan, bez obiecywanych dat.","tl.today":"Dziś","tl.planned":"w planach","tl.doing":"w toku","tl.cards.one":"{n} karta","tl.cards.other":"{n} karty","join.h2":"Dołącz","join.lede":"AI-gile budują brodaty dziwak z AuDHD i kilkoma bitwami o zdrowie psychiczne oraz bardzo wielu cierpliwych agentów. Na razie jest prywatne, w zamkniętej alfie z przyjaciółmi. Chcesz spróbować, gdy się otworzy?","join.btn":"Zgłoś zainteresowanie","join.small":"Napiszemy do Ciebie e-mailem i nic więcej","footer.tag":"AI-gile. Bez trackerów, bez ciasteczek, bez kawy na stojąco.","footer.licence":"Licencja biznesowa","footer.status":"Status","footer.privacy":"Co przechowujemy","footer.thanks":"Rozmowy dzięki ChilledChat","form.sending":"Wysyłanie…","form.failed":"Nie udało się: spróbuj ponownie później.","form.offline":"Nie można połączyć się z AI-gile: spróbuj ponownie później.","form.keep":"Używamy tego tylko po to, żeby Ci odpowiedzieć, a potem to usuwamy. Bez trackerów, bez ciasteczek.","form.keepLink":"Co przechowujemy","interest.title":"AI-gile: powiadom mnie, gdy ruszy alfa","interest.description":"Zostaw e-mail, żeby dowiedzieć się, kiedy ruszy zamknięta alfa lub beta AI-gile.","interest.h1":"🔔 Powiadom mnie, gdy ruszy","interest.lede":"AI-gile jest w zamkniętej pre-alfie. Zostaw e-mail, a napiszemy raz, gdy znajdzie się dla Ciebie miejsce.","interest.email":"Twój e-mail","interest.which":"Który test?","interest.alpha":"Zamknięta alfa: wcześnie, surowo, dużo zmian","interest.beta":"Beta: spokojniej, później","interest.both":"Obojętnie, co pierwsze","interest.submit":"Zapisz mnie na listę","interest.thanks":"Dzięki! Jesteś na liście.","licence.title":"AI-gile: licencja biznesowa","licence.description":"Używasz AI-gile w firmie? Poproś o bezpłatną licencję biznesową.","licence.h1":"📜 Licencja biznesowa","licence.lede":"Używasz AI-gile w pracy? Napisz, kim jesteś i czym się zajmujesz. Jeśli robi to coś dobrego, licencja jest bezpłatna.","licence.company":"Firma","licence.website":"Strona internetowa","licence.what":"Czym się zajmujesz","licence.how":"Jak to pomaga światu","licence.email":"E-mail","licence.submit":"Wyślij wniosek","licence.thanks":"Dzięki! Odpowiemy e-mailem.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Wszystko spokojnie","status.intro":"Czy AI-gile teraz działa? Ta strona co 5 minut sprawdza stronę internetową, udostępnianie tablic, rozmowy i pobieranie.","status.up":"Działa (odpowiedź w {ms} ms)","status.slow":"Brak odpowiedzi przy ostatnim sprawdzeniu, ponawiam","status.down":"Nie działa: brak odpowiedzi przy dwóch ostatnich sprawdzeniach","status.svc.web":"Strona internetowa","status.svc.web.offers":"Ta strona: czym jest AI-gile i formularz zgłoszeniowy","status.svc.boards":"Udostępnianie tablic","status.svc.boards.offers":"Publiczne tablice, wiadomości między znajomymi i zaproszenia","status.svc.calls":"Rozmowy","status.svc.calls.offers":"Głos, wideo i udostępnianie ekranu w AI-gile","status.svc.download":"Pobieranie","status.svc.download.offers":"Instalator na Windows i linki z zaproszeniami","status.checking":"Sprawdzanie…","status.offline":"Nie można teraz połączyć się z usługą statusu (ponawiam)","status.updated":"zaktualizowano {ago}","status.justNow":"przed chwilą","status.min":"{n} min temu","status.hours":"{n} godz. temu","status.days":"{n} dni temu","privacy.title":"AI-gile: co przechowujemy","privacy.h1":"Co przechowujemy","privacy.lede":"W skrócie: tylko to, co nam wyślesz, i nie na długo.","privacy.only":"Tylko to, co nam wyślesz: to, co wpiszesz w formularz, na przykład Twój e-mail. Nic więcej o Tobie.","privacy.sealed":"Dane są zapieczętowane, więc nasz serwer nie może ich odczytać: w Twojej przeglądarce, zanim zostaną wysłane (w starszej przeglądarce w chwili, gdy dotrą). Otworzyć je może tylko nasza własna tablica.","privacy.server":"Usuwamy je z serwera, gdy tylko dotrą do naszej tablicy. Wszystko, co leży tam dłużej niż 30 dni, i tak zostaje usunięte.","privacy.board":"Trzymamy je na naszej tablicy tylko do czasu, aż Ci odpowiemy, a potem usuwamy je również stamtąd.","privacy.none":"Bez trackerów, bez ciasteczek, bez analityki.","privacy.local":"Twój język i wybór jasnego lub ciemnego motywu zostają w Twojej przeglądarce. Nigdy nie są do nas wysyłane.","privacy.ask":"Chcesz, żeby zniknęły wcześniej? Odpowiedz na naszego e-maila i daj znać.","live.h2":"Zobacz, jak to powstaje, na żywo","live.caption":"Każda karta jest ukryta: widzisz kształt pracy, a nie słowa.","live.watching.one":"na żywo: ogląda {n}","live.watching.other":"na żywo: oglądają {n}","live.last.now":"Ostatnia karta przesunięta przed chwilą","live.last.min.one":"Ostatnia karta przesunięta {n} min temu","live.last.min.other":"Ostatnia karta przesunięta {n} min temu","live.last.hour.one":"Ostatnia karta przesunięta {n} godz. temu","live.last.hour.other":"Ostatnia karta przesunięta {n} godz. temu","live.last.day.one":"Ostatnia karta przesunięta {n} dzień temu","live.last.day.other":"Ostatnia karta przesunięta {n} dni temu","live.offline":"Tablica na żywo bierze krótki oddech. Zajrzyj wkrótce ponownie.","live.cols":"Backlog|Do zrobienia|W toku|Zespół sprawdza|Do przetestowania przez Ciebie|Dla zespołu|Gotowe","pitch.words.few":"{n} słowa","pitch.words.many":"{n} słów","pitch.letters.few":"{n} litery","pitch.letters.many":"{n} liter","pitch.chars.few":"{n} znaki","pitch.chars.many":"{n} znaków","count.line.html.few":"{n} karty na tablicy w tej chwili","count.line.html.many":"{n} kart na tablicy w tej chwili","tl.cards.few":"{n} karty","tl.cards.many":"{n} kart"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboty.","Zlecone."]},{"n":2,"texts":["Kanban robotów.","Agenci, uporządkowani.","Pomysły, zbudowane."]},{"n":3,"texts":["Kanban dla robotów.","Pomysły stają się funkcjami.","Darmowy kanban agentów."]},{"n":5,"texts":["Tablica kanban prowadzona przez agentów.","Ty piszesz karty. Agenci budują.","Darmowe, lokalne, testowane, odrobinę zwariowane."]},{"n":8,"texts":["Darmowy kanban, w którym pracują agenci AI.","Zapisz pomysł. Agenci go zbudują. Ty akceptujesz.","Agile dla jednego człowieka i wielu cierpliwych robotów."]},{"n":13,"texts":["Tablica kanban na Twoim komputerze, gdzie karty biorą agenci AI.","Zapisz swój pomysł na karcie. Cały zespół agentów go zbuduje, a tester AI sprawdzi, czy działa.","Za darmo, bez kont, bez trackerów: tablica, trochę robotów i Ty u steru."]},{"n":21,"texts":["AI-gile to tablica kanban do pracy z agentami programistycznymi AI. Oni biorą karty; Ty testujesz i akceptujesz.","Każdy projekt dostaje lidera i zespół agentów AI. Skomentuj dowolną kartę, a zespół bierze się do pracy.","Darmowa, osobista tablica zadań, która działa na Twoim własnym komputerze, bez żadnych kont. Pracują roboty, ale to Ty decydujesz, co jest gotowe."]},{"n":34,"texts":["Wrzucasz pomysły na tablicę. Zespół agentów AI zamienia je w działające funkcje, testuje i oddaje z krokami do wypróbowania. Nic nie liczy się jako zrobione, dopóki Ty tego nie powiesz.","AI-gile to domowa tablica kanban, którą Rich zbudował przy ogromnej pomocy agentów, którymi teraz zarządza. Jest darmowa, działa na Twoim komputerze i jest dzielona z przyjaciółmi, a nie sprzedawana.","Wyobraź sobie zwykłą tablicę kanban z kolumnami od Backlogu do Gotowe, tyle że karty biorą agenci AI. Zgłaszają postępy, pytają, gdy utkną, i zawsze czekają na Twój kciuk w górę."]},{"n":55,"texts":["AI-gile to tablica kanban, na której zespół składa się z agentów AI. Każdy projekt ma lidera, który planuje pracę, i pomocników, którzy ją wykonują. Gdy funkcja jest gotowa, tester AI ją wypróbowuje i robi zrzut ekranu, a potem trafia na Twój stos. Zaakceptuj ją albo skomentuj, a oni poprawią.","Zaczęło się jako sposób jednej osoby na ogarnięcie wielu sesji programowania z AI naraz, a urosło do prawdziwej tablicy. Działa na Twojej maszynie, nie wymaga konta i nie ma trackerów. Jest darmowa dla przyjaciół i ciekawskich. Jest też niedokończona, więc spodziewaj się chropowatości i od czasu do czasu niespodzianki.","Powiedzmy sobie szczerze. Pomysły nadal musisz mieć sam i wyniki nadal musisz sprawdzać. AI-gile robi wszystko pomiędzy: trzyma karty w porządku, budzi właściwego agenta, gdy napiszesz komentarz, pokazuje dokładnie, co się zmieniło, i zbiera całą resztę w jeden krótki stos, który czeka właśnie na Ciebie."]},{"n":89,"texts":["AI-gile to darmowa tablica kanban, którą uruchamiasz na własnym komputerze. Zamiast ludzi każdy projekt ma zespół agentów AI: lidera, który zamienia Twoje pomysły w karty i plan, oraz pomocników, którzy biorą karty według priorytetu. Gdy coś jest zbudowane, tester AI wykonuje kroki testowe i pokazuje, co zobaczył. Potem całość czeka na jednym stosie zwanym Dla Ciebie. Akceptujesz albo komentujesz, a zespół próbuje jeszcze raz. Nic nie trafia do Gotowe bez Ciebie.","Kilka rzeczy, których możesz się nie spodziewać. Nocna straż uzupełnia kolumnę Do zrobienia, gdy śpisz, wybierając karty, które nie potrzebują Twojej odpowiedzi. Licznik tokenów pokazuje, ile agenci zużyli dziś i w tym tygodniu, a Tryb bez tokenów każe im przestać wydawać. Możesz pisać do przyjaciół, a prywatne wiadomości są szyfrowane od końca do końca. Tablica mówi w około 120 językach, w tym po niderlandzku, flamandzku, piracku i klingońsku. Nic z tego nie kosztuje ani grosza i nikt nie chce Ci tego sprzedać.","AI-gile to mały, osobisty projekt, a nie firma. Rich chciał opiekować się kilkoma projektami z AI bez otwierania każdej aplikacji osobno, żeby zobaczyć, co słychać, więc razem z agentami zbudował do tego tablicę, a potem tą samą tablicą zbudował resztę jej samej. Jest w zamkniętej pre-alfie, czyli działa, przeważnie, dla garstki przyjaciół. Nie ma cennika, newslettera ani planu podbijania świata. Jeśli brzmi to przydatnie, poproś o dostęp, gdy otworzy się trochę szerzej."]},{"n":144,"texts":["AI-gile to tablica kanban dla jednego człowieka i bardzo wielu agentów AI. Działa na Twoim własnym komputerze i jest całkowicie darmowa. Dodajesz projekty, a każdy projekt dostaje lidera i mały zespół. Rozmawiasz z liderem, trochę jak na Discordzie, i opisujesz swój pomysł; lider zamienia go w karty i plan, po czym czeka, aż naciśniesz Go. Zespół przechodzi przez karty według priorytetu, korzystając z prostego wiersza poleceń stworzonego dla modeli językowych. Zanim cokolwiek wróci do Ciebie, tester AI wykonuje wszystkie kroki w kopii aplikacji i dołącza zrzut ekranu tego, co zobaczył. Gotowa praca ląduje na Twoim stosie razem ze zmienionymi plikami i diffem. Akceptujesz ją albo zostawiasz komentarz, a wtedy zespół się budzi i próbuje jeszcze raz. Tylko Ty możesz przenieść kartę do kolumny Gotowe, nikt inny i nigdy.","Dzień z AI-gile, mniej więcej. Wieczorem zostawiasz kilka komentarzy: ten przycisk jest w złym miejscu, tamta lista powinna być posortowana, a czy mógłby być tryb ciemny. Idziesz spać. Agenci czytają komentarze, wprowadzają zmiany, testują je i oddają Ci wyniki. Jeśli kolumna Do zrobienia się opróżni, nocna straż uzupełnia ją kartami z backlogu, które nie potrzebują Twojej odpowiedzi. Rano czeka jeden krótki stos: kilka pytań i kilka rzeczy do wypróbowania, każda z krokami, za którymi trafi nawet niewyspana osoba, i ze zrzutem ekranu działającej wersji. Przeklikujesz wszystko, akceptujesz to, co dobre, i odsyłasz resztę. Licznik tokenów pokazuje, ile to wszystko zużyło, a Tryb bez tokenów czeka na chudsze tygodnie. Potem jesz śniadanie, w czym agenci jeszcze Ci nie pomogą.","Najpierw to, czym AI-gile nie jest. Nie jest startupem, nie jest na sprzedaż i nikt nie zbiera Twoich danych. To darmowa tablica, która działa na Twoim komputerze, bez kont, bez trackerów i bez ciasteczek. A czym jest: jednym uporządkowanym miejscem, w którym widzisz wszystkie projekty z AI naraz, z zespołem agentów robiącym karty i Tobą podejmującym decyzje. Łączy powiązane karty, poprawia zagmatwane tytuły i pilnuje, żeby kod pozostał szczupły. Mówi w około 120 językach, od niderlandzkiego i flamandzkiego po piracki i klingoński. Przyjaciele mogą do siebie pisać, prywatnie i szyfrowanie. Zbudowali ją Rich i bardzo wielu cierpliwych agentów, głównie korzystając z niej samej. Jest w zamkniętej pre-alfie, więc w niektórych miejscach bywa surowa. Jeśli brzmi to zabawnie, poproś ładnie, a może wejdziesz wcześniej."]}],"quips":{"1":"Jedno słowo. Odważnie. Może za odważnie.","3":"Trzy słowa. Już szczerzej niż większość stron produktów.","8":"Osiem słów. Nadal krócej niż stand-up.","21":"Długości to zresztą story pointy. Oczywiście, że tak.","55":"Pięćdziesiąt pięć słów. Dwie karty skończyły się, gdy to czytasz.","144":"To ta długa. Nie ma 233. Agenci poszli spać."}},"timeline":{"first-idea.name":"Pierwszy pomysł","first-idea.line":"Najpierwsza rozmowa, zanim powstała choćby linijka kodu.","first-board.name":"Pierwsza tablica","first-board.line":"Tablica, która śledzi własną budowę: karty, kolumny, przeciąganie, projekty.","team-roles.name":"Zespół i role","team-roles.line":"Profile agentów, szablony zespołów, przestrzenie i kto za co odpowiada.","install.name":"Instalacja i wydania","install.line":"Zip, który przyjaciel zainstaluje, z samoaktualizacją, kanałami i cofaniem.","usage-saver.name":"Oszczędzanie zużycia","usage-saver.line":"Mierzenie kosztu uruchomień, szczupły kod, oszczędzanie limitu.","friends.name":"Przyjaciele i udostępnianie","friends.line":"Prywatne wiadomości, zaszyfrowany przekaźnik, zaproszenia, role i wspólne projekty.","languages.name":"Języki","languages.line":"Każdy tekst na ekranie w pliku językowym, na początek niderlandzki i flamandzki.","ai-tester.name":"Tester AI","ai-tester.line":"Tester sprawdza każde przekazanie jako pierwszy i pokazuje, co zobaczył.","website.name":"Strona internetowa","website.line":"aigile.lol, strona zapowiedzi i ta oś czasu.","streaming.name":"Czat i streaming","streaming.line":"Discord, Twitch, OBS, tryb streamera, GIF-y i emoji.","no-ai.name":"Wersja bez AI","no-ai.line":"Tablica dla ludzi, którzy programują bez AI, oraz tablice publiczne.","night-watch.name":"Nocna straż","night-watch.line":"Stróż i Scrum Master pilnują zespołów, gdy śpisz.","p-more.name":"Cała reszta","p-more.line":"Mniejsze pomysły, które wciąż czekają na swoją kolej.","p-android.name":"Telefon i Android","p-android.line":"Dostęp do tablicy z telefonu, a potem natywna aplikacja na Androida.","p-release.name":"Alfa i dalej","p-release.line":"Zamknięta alfa, strona na żywo, potem beta.","p-languages.name":"Więcej języków","p-languages.line":"130 języków i tryb immersji dla uczących się.","p-engines.name":"Więcej silników AI","p-engines.line":"Wybierz Claude, Codex, Gemini, Copilot albo Cursor dla każdego agenta.","p-pro.name":"Praktyka zawodowa","p-pro.line":"Etykiety ryzyka, bramki scalania, karty incydentów i bariery ochronne.","p-self.name":"Dbanie o Ciebie","p-self.line":"Tryb zmęczenia, przypomnienia o dbaniu o siebie i 4:20.","p-servers.name":"Serwery i skala","p-servers.line":"Globalne ustawienia serwera, role i planowanie wzrostu.","p-livestream.name":"Dodatki do streamów","p-livestream.line":"Czat Twitcha, własne emoji i publiczny podgląd na żywo."},"words":{"button":"📖 Żargon branżowy","h":"📖 Słowniczek","intro":"Słowa, które spotkasz w AI-gile, prostym językiem: budowanie, bezpieczne wprowadzanie zmian, utrzymanie działania dla ludzi, którzy z tego korzystają, i praca w zespole z AI.","search":"Szukaj słowa…","none":"Żadne słowo nie pasuje.","close":"Zamknij","count":{"one":"{count} słowo","other":"Słów: {count}"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Budowanie"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Bezpieczne zmiany"},{"id":"run","name":"🛎️ Utrzymanie usługi"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have.","also":["feasible"]},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["prioritising","prioritise","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Pomysły i praca jeszcze niezaplanowana. Nic stamtąd nie jest robione, dopóki nie trafi do kolumny Do zrobienia."},{"id":"sprint","g":"agile","word":"Sprint","text":"Krótki odcinek pracy (często tydzień lub dwa) z uzgodnionym zestawem kart do skończenia.","also":["sprinty","sprint"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Krótka odprawa: co każdy zrobił, co zrobi dalej i co go blokuje.","also":["standup","stand-upy","standupy"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Tablica z kolumnami (Do zrobienia, W toku, Gotowe), po której karty przesuwają się od lewej do prawej w miarę pracy."},{"id":"wip","g":"agile","word":"Limit WIP","text":"Work in progress: najwięcej kart, jakie powinna mieć kolumna, żeby zespół kończył rzeczy, zanim zacznie kolejne.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definicja Zrobione","text":"Krótka lista zespołu, co znaczy „skończone”, na przykład przetestowane i wyjaśnione, zanim karta trafi do Ciebie. Jej bliźniaczka, Definicja Gotowe do startu, mówi, kiedy karta jest na tyle jasna, żeby zacząć.","also":["Definition of Done","DoD","Definicja Gotowe do startu","Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"Spojrzenie wstecz na to, jak pracuje zespół, żeby ustalić jedną rzecz do poprawy. W AI-gile retro proponuje zmianę w sposobie pracy zespołu, a Ty mówisz Go albo Jeszcze nie.","also":["retrospektywa","retrospektywy"]},{"id":"swarm","g":"agile","word":"Rój","text":"Wszystkie ręce na pokład: każdy zespół odkłada inną pracę i pomaga przy jednym pilnym projekcie, dopóki sprawa nie zostanie załatwiona. Inne projekty w tym czasie czekają.","also":["tryb roju","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Ktoś, kto dba o płynność pracy: wyłapuje utknięte karty, popędza zespoły i przypomina Ci, co czeka. W AI-gile Lead Scrum Master robi to we wszystkich projektach.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["SAFe","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Folder projektu z kodem i pełną historią commitów, zwykle trzymany też na GitHubie.","also":["repozytorium"]},{"id":"branch","g":"build","word":"Branch","text":"Osobna linia pracy w kodzie, żeby zmieniać rzeczy bez dotykania głównej wersji.","also":["branche","gałąź","gałęzie"]},{"id":"commit","g":"build","word":"Commit","text":"Zapisana migawka kodu z krótką notatką o tym, co się zmieniło. Zawsze możesz do niej wrócić.","also":["commity"]},{"id":"push","g":"build","word":"Push","text":"Wysłanie zapisanych migawek (commitów) z tego komputera na GitHub, żeby były zabezpieczone i udostępnione."},{"id":"merge","g":"build","word":"Merge","text":"Włączenie zmian z brancha z powrotem do głównej wersji."},{"id":"pr","g":"build","word":"Pull request","text":"Prośba o sprawdzenie zmian z brancha i włączenie ich do głównej wersji.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktoryzacja","text":"Porządkowanie kodu bez zmiany tego, co robi: mniejsze pliki, jaśniejsze nazwy, mniej powtórzeń."},{"id":"bug","g":"build","word":"Bug","text":"Coś, co nie działa tak, jak powinno.","also":["bugi","błąd","błędy"]},{"id":"peerreview","g":"build","word":"Recenzja przez innych","text":"Druga para oczu: inne AI sprawdza pracę z każdej karty, zanim trafi do Ciebie, więc mniej błędów przechodzi dalej.","also":["peer review","code review","przegląd kodu"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor.","also":["responsive"]},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiled","compiler","compiling"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Wypróbowanie skończonej pracy, by sprawdzić, czy robi to, czego oczekiwano, zanim ją zaakceptujesz.","also":["testy","testowanie"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Skrót od quality assurance, czyli zapewnienie jakości: automatyczne sprawdzenia, które działają, zanim cokolwiek pójdzie na żywo. Gdy QA jest czerwone, coś się nie udało i nie można tego wypuścić, dopóki nie zostanie naprawione.","also":["kontrola jakości","testy jakości"]},{"id":"testpile","g":"test","word":"Stos testów","text":"Gotowe karty, które czekają, aż je wypróbujesz, jedna po drugiej. Zaakceptuj jedną albo odeślij ją z notatką, a pojawi się następna.","also":["stosy testów","test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["coverage","code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Wypuszczenie nowej wersji na żywo, na przykład na serwer, z którego korzystają ludzie."},{"id":"release","g":"change","word":"Wydanie","text":"Nazwana paczka gotowej pracy, która idzie na żywo razem, z krótkimi notatkami o tym, co się zmieniło. 🚀 Wydania pisze notatki na podstawie zrobionych kart.","also":["wydania","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Powrót do ostatniej wersji, która działała, gdy nowa sprawia kłopoty. W AI-gile powstaje z tego lista kroków cofania, zapisanych przy każdej zmianie.","also":["wycofanie","cofnięcie zmian","wycofać"]},{"id":"live","g":"change","word":"Na żywo","text":"Prawdziwa wersja, z której korzystają ludzie, w odróżnieniu od kopii do próbowania. Programiści mówią na nią też produkcja.","also":["produkcja","prod"],"noTip":1},{"id":"change","g":"change","word":"Zmiana","text":"Zaplanowana zmiana w czymś, na czym ludzie polegają, najpierw spisana: co, dlaczego, ryzyko, kiedy i jak ją cofnąć. Zacznij od 🔀 Zgłoś zmianę.","also":["zmiany","wniosek o zmianę","change request"],"noTip":1},{"id":"risk","g":"change","word":"Ryzyko","text":"Coś, co może pójść nie tak, ocenione według tego, jak jest prawdopodobne i jak poważne by było. ⚠️ Ryzyka trzyma je na jednej liście, od najwyższej oceny, każde z datą ponownego przejrzenia.","also":["ryzyka","rejestr ryzyk"]},{"id":"chgwin","g":"change","word":"Okno zmian","text":"Pory, w których zmiany mogą iść na żywo, na przykład spokojny wtorkowy wieczór. Poza oknem karty zmiany nie da się zakończyć, chyba że to sytuacja awaryjna.","also":["okna zmian","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Szybkie głosowanie tuż przed wypuszczeniem zmiany: każda osoba, która musi ją zatwierdzić, mówi Go albo No go. Zmiana idzie dalej tylko wtedy, gdy wszyscy się zgadzają.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Zatwierdzenie","text":"Czekanie na „tak”, zanim praca się zacznie. Karta zgłoszona przez znajomego albo zmiana czeka w ✅ Zatwierdzeniach, aż ją zatwierdzisz albo odrzucisz.","also":["zatwierdzenia","akceptacja"]},{"id":"quiettime","g":"change","word":"Cicha pora","text":"Okres, na przykład stream, demo albo noc, w którym nic nie idzie na żywo. Zespoły dalej pracują i testują, ale wypuszczanie czeka, aż się skończy. Gdzie indziej nazywa się to zamrożeniem zmian.","also":["ciche pory","zamrożenie zmian","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company.","also":["hosted"]},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Usługa","text":"Coś zbudowanego przez Ciebie, na czym ludzie polegają, na przykład strona albo aplikacja, pilnowane tak, żeby dalej działało. Zaznacz „Ten projekt jest usługą” i napisz, co oferuje, kto z niej korzysta i kto ma dyżur.","also":["usługi","serwis"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Sprawdzanie dostępności","text":"Automatyczne sprawdzenie co kilka minut, czy Twoja usługa wciąż odpowiada. Jeśli kilka razy z rzędu się nie uda, AI-gile sam otwiera kartę incydentu.","also":["uptime","dostępność","uptime check"]},{"id":"statuspage","g":"run","word":"Strona statusu","text":"Publiczna strona, która pokazuje, czy usługa działa (zielony, pomarańczowy albo czerwony), z najnowszą informacją, żeby jej użytkownicy mogli sprawdzić, zamiast pytać.","also":["strony statusu","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Miejsce, do którego trafiają pytania i zgłoszenia od ludzi korzystających z twojej usługi. AI-gile przydziela każde do prośby, incydentu albo pomysłu i mówi, gdy wygląda na coś, co już zgłoszono.","also":["biuro obsługi","biurko","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Prośba o usługę","text":"Ktoś prosi o coś zwykłego, na przykład nowe konto albo trochę pomocy, zamiast zgłaszać, że coś jest zepsute. Czeka na swoją kolej; incydent idzie pierwszy.","also":["prośby o usługę","prośba"]},{"id":"incident","g":"run","word":"Incydent","text":"Coś, co właśnie teraz nie działa dla ludzi, którzy z tego korzystają, na przykład strona leży. Karta 🔥 incydentu wskakuje na początek kolejki: najpierw trzeba to znowu uruchomić.","also":["incydenty","awaria"]},{"id":"major","g":"run","word":"Poważny incydent","text":"Duży incydent: dotyka wielu ludzi albo zagraża pieniądzom lub danym. Jeden przycisk rzuca na niego wszystkie zespoły (rój), budzi dyżurnego i co 30 minut prosi o informację o stanie.","also":["poważne incydenty","major incident"]},{"id":"oncall","g":"run","word":"Dyżur","text":"Bycie osobą, która reaguje, gdy coś się zepsuje, nawet w nocy. Każda usługa ma dyżurnego członka zespołu, którego budzi się jako pierwszego przy jej incydentach.","also":["dyżurny","on call","on-call","w pogotowiu"]},{"id":"replyby","g":"run","word":"Termin odpowiedzi","text":"Jak długo karta może czekać na pierwszą odpowiedź, na przykład godzinę przy incydencie. Potem dostaje czerwony zegar, żeby nic nie zostało po cichu zapomniane. Nazywa się to też docelowym czasem reakcji.","also":["terminy odpowiedzi","czas reakcji","docelowy czas reakcji"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Krótka analiza po incydencie: co się stało, co pomogło i co zmienić, bez obwiniania kogokolwiek. Incydentu nie da się zamknąć bez niej.","also":["analiza poincydentalna","postmortem","przegląd po incydencie"]},{"id":"problem","g":"run","word":"Problem","text":"Ukryta przyczyna jednego lub kilku incydentów. Karta 🧩 problemu grupuje incydenty, które ciągle wracają, żeby przyczynę znaleźć i naprawić na dobre.","also":["problemy"],"noTip":1},{"id":"rootcause","g":"run","word":"Przyczyna źródłowa","text":"Prawdziwy powód, dla którego coś się zepsuło, a nie tylko to, co było widać. Napraw przyczynę źródłową, a incydent przestanie wracać.","also":["przyczyny źródłowe","root cause","pierwotna przyczyna"]},{"id":"workaround","g":"run","word":"Obejście","text":"Sposób, żeby wszystko działało, zanim będzie gotowa prawdziwa naprawa, na przykład restart czegoś, co się zawiesza. Zapisuje się je na karcie problemu, żeby nikt nie musiał wymyślać go od nowa.","also":["obejścia","workaround","rozwiązanie tymczasowe"]},{"id":"knownerror","g":"run","word":"Znany błąd","text":"Problem, którego przyczyna jest znana i który ma obejście, ale nie jest jeszcze naprawiony. 🧩 Znane błędy je wymienia, żeby każdy korzystał z obejścia, zamiast szukać od nowa.","also":["znane błędy","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Instrukcja krok po kroku, jak naprawić znany rodzaj kłopotu, żeby za każdym razem robić to tak samo i szybko. Po dużym incydencie zespół może zaproponować taki runbook do Twojej akceptacji.","also":["runbooki","instrukcja postępowania","procedura"]},{"id":"ci","g":"run","word":"Element konfiguracji","text":"Jedna rzecz, od której zależy twoja usługa, na przykład serwer, domena, certyfikat, klucz albo dostawca. 🗂️ Elementy konfiguracji wymienia je dla każdej usługi, więc widać, czego dotyczy incydent i co trzeba odnowić albo zabezpieczyć kopią.","also":["elementy konfiguracji","elementów konfiguracji"]},{"id":"expiry","g":"run","word":"Data ważności","text":"AI-gile pilnuje dat, na przykład kiedy wygasa certyfikat albo domena. Na 30 dni przed tą datą tworzy jedną kartę o odnowienie, żeby nic nie przestało działać niespodziewanie.","also":["daty ważności","wygaśnięcie","pilnowanie ważności"]},{"id":"backup","g":"run","word":"Kopia zapasowa","text":"Zapisana wcześniej kopia Twoich danych, na wypadek gdyby coś zginęło albo się uszkodziło. AI-gile codziennie robi kopię zapasową Twoich tablic.","also":["kopie zapasowe","backup","backupy"]},{"id":"restore","g":"run","word":"Przywracanie","text":"Odtwarzanie danych z kopii zapasowej. Kopia naprawdę się liczy dopiero wtedy, gdy wiesz, że da się ją przywrócić, więc warto to czasem sprawdzić.","also":["przywrócenie","przywrócone","restore"]},{"id":"svcreview","g":"run","word":"Przegląd usługi","text":"Spojrzenie wstecz na jeden miesiąc usługi: otwarte i naprawione incydenty, jak szybko ludzie dostali odpowiedź, dostępność i zużyte tokeny. Przegląd miesięczny pokazuje to dla każdej usługi.","also":["przeglądy usługi","przegląd miesięczny","przeglądy miesięczne"]},{"id":"accessreview","g":"run","word":"Przegląd dostępu","text":"Co 90 dni sprawdzamy, kto nadal ma dostęp: linki udostępniania, role znajomych i przechowywane sekrety. Każdy z nich zachowujesz albo usuwasz, żeby stary dostęp nie zostawał na zawsze.","also":["przeglądy dostępu"]},{"id":"improvements","g":"run","word":"Lista usprawnień","text":"Wszystko, w czym zespół postanowił się poprawić, w jednym miejscu: sugestie z retrospektyw, działania z przeglądów i naprawy problemów, każde ze swoim statusem. Znajdziesz to pod 📈 Usprawnienia.","also":["listy usprawnień","usprawnienia"]},{"id":"tokencap","g":"run","word":"Limit tokenów","text":"Miesięczny limit tokenów, które mogą zużyć agenci usługi. Przy 80% dostajesz ostrzeżenie; przy 100% ich praca w tle czeka do następnego miesiąca albo do chwili, gdy podniesiesz limit.","also":["limity tokenów","miesięczny limit tokenów"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day.","also":["managing a service"]},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice.","also":["monitored"]},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing.","also":["lag"]},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first line","second line","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service.","also":["redundant"]},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers","hand over"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal.","also":["virus","viruses"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI, które samo pracuje nad zadaniem: czyta kod, wprowadza zmiany, uruchamia sprawdzenia i melduje się z wynikami.","also":["agenci"]},{"id":"token","g":"ai","word":"Token","text":"Jednostka, w której liczy się zużycie AI: mniej więcej kilka liter przeczytanego lub napisanego tekstu. Mniej tokenów, więcej planu zostaje.","also":["tokeny"]},{"id":"hook","g":"ai","word":"Hook","text":"Małe polecenie, które uruchamia się samo w ustalonym momencie, np. gdy startuje sesja AI, żeby zespół usłyszał Twoje komentarze.","also":["hooki","haki"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results.","also":["prompting"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals","evaluations"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers.","also":["purchasing"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
